<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{CorporateAccount,CorporateInvoice,GroupReservation,HotelEvent,TravelAgent};
class SalesDashboardController extends Controller{public function __invoke(){ $p=auth()->user()->property_id;return view('sales.dashboard',['companies'=>CorporateAccount::where('property_id',$p)->count(),'agents'=>TravelAgent::where('property_id',$p)->count(),'events'=>HotelEvent::where('property_id',$p)->whereDate('starts_at','>=',today())->count(),'groups'=>GroupReservation::where('property_id',$p)->whereIn('status',['tentative','confirmed'])->count(),'receivables'=>(float)CorporateInvoice::where('property_id',$p)->sum('balance'),'overdue'=>(float)CorporateInvoice::where('property_id',$p)->where('balance','>',0)->whereDate('due_date','<',today())->sum('balance')]);}}
